package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

/**
 * The single definition of a "business day" for owner registration: Monday–Friday. A date
 * that falls on a Saturday or Sunday is rolled forward to the following Monday; a weekday is
 * returned unchanged. Used so every effective registration date — whether supplied in the
 * request or defaulted to the server date — lands on a business day, and so the daily
 * create-limit buckets owners by that same adjusted day.
 */
final class BusinessDay {

    private BusinessDay() {
    }

    /** {@code date} rolled forward to the next Monday when it falls on a weekend, else unchanged. */
    static LocalDate adjust(LocalDate date) {
        switch (date.getDayOfWeek()) {
            case SATURDAY:
                return date.plusDays(2);
            case SUNDAY:
                return date.plusDays(1);
            default:
                return date;
        }
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of an owner "namesake": two owners are namesakes when they share
 * the same first name and last name, compared case-insensitively (leading and trailing
 * whitespace ignored). Provides the membership test used to count how many existing owners
 * a new owner shares a name with.
 *
 * @see CountNamesakes counts the matching owners at registration.
 */
final class Namesake {

    private Namesake() {
    }

    /** Whether {@code owner} is a namesake of the owner named {@code firstName} {@code lastName}. */
    static boolean matches(Owner owner, String firstName, String lastName) {
        return normalize(owner.getFirstName()).equals(normalize(firstName))
                && normalize(owner.getLastName()).equals(normalize(lastName));
    }

    /** A name trimmed and lower-cased, so comparison is case-insensitive. */
    private static String normalize(String value) {
        return value == null ? "" : value.strip().toLowerCase(Locale.ROOT);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * The single definition of an owner "household": owners sharing the same last name and
 * postcode. The last name is compared case-insensitively with runs of whitespace collapsed
 * to a single space; the postcode is taken as stored. Provides the deterministic identifier
 * shared by the household.
 *
 * <p>The identifier is derived deterministically from the normalized last name and postcode
 * — the first 12 upper-case hex characters of SHA-256 over {@code normalizedLastName + '|' +
 * postcode} — so every owner with the same last name and postcode resolves to the same value
 * regardless of creation order, and no owner-to-owner linking is needed.
 *
 * @see AssignHousehold stamps each owner with its computed identifier.
 * @see EnsureUniqueIdentity blocks a second owner in the same household unless it opts in.
 */
final class Household {

    /** Length of the household identifier, in hex characters. */
    private static final int ID_LENGTH = 12;

    private Household() {
    }

    /** The stable identifier shared by every owner in the household keyed by {@code lastName}
     *  and {@code postcode}. */
    static String id(String lastName, String postcode) {
        String key = normalizeName(lastName) + "|" + (postcode == null ? "" : postcode);
        return Sha256.hex(key, ID_LENGTH);
    }

    /** A last name trimmed and lower-cased, with internal whitespace runs collapsed to a single space. */
    private static String normalizeName(String value) {
        return value == null ? "" : value.strip().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

